-- The content calendar template, as Postgres tables. Made by baseToSql (@svgrid/enterprise/base);
-- the svgrid: comments keep what SQL has no type for, so baseFromDatabase opens it as the same base.

create table "posts" (
  "id" text primary key default gen_random_uuid()::text,
  "title" text,
  "stage" text,
  "channels" text[],
  "author" text,
  "campaign_id" text,
  "publish" date,
  "cover" jsonb,
  "words" double precision,
  "brief" text,
  "link" text
);
create table "campaigns" (
  "id" text primary key default gen_random_uuid()::text,
  "name" text,
  "goal" text,
  "owner" text,
  "starts" date,
  "ends" date
);

comment on column "posts"."title" is 'svgrid:{"field":"title","header":"Title","width":300,"fieldType":"text"}';
comment on column "posts"."stage" is 'svgrid:{"field":"stage","header":"Stage","width":130,"fieldType":"singleSelect","fieldProps":{"options":[{"value":"Idea","color":"#94a3b8"},{"value":"Drafting","color":"#2d7ff9"},{"value":"In review","color":"#fcb400"},{"value":"Scheduled","color":"#8b46ff"},{"value":"Published","color":"#20c933"}]}}';
comment on column "posts"."channels" is 'svgrid:{"field":"channels","header":"Channels","width":200,"fieldType":"multiSelect","fieldProps":{"options":[{"value":"Blog","color":"#2d7ff9"},{"value":"Newsletter","color":"#ff6f2c"},{"value":"LinkedIn","color":"#18bfff"},{"value":"YouTube","color":"#f82b60"},{"value":"Podcast","color":"#8b46ff"}]}}';
comment on column "posts"."author" is 'svgrid:{"field":"author","header":"Author","width":160,"fieldType":"user"}';
comment on column "posts"."campaign_id" is 'svgrid:{"field":"campaign","header":"Campaign","width":170,"fieldType":"link","fieldProps":{"table":"campaigns","multiple":false,"inverse":"posts"}}';
comment on column "posts"."publish" is 'svgrid:{"field":"publish","header":"Publish date","width":160,"fieldType":"date","fieldProps":{"dateFormat":"friendly"}}';
comment on column "posts"."cover" is 'svgrid:{"field":"cover","header":"Cover","width":120,"fieldType":"attachment"}';
comment on column "posts"."words" is 'svgrid:{"field":"words","header":"Words","width":100,"fieldType":"number","fieldProps":{"format":"integer","summary":"sum"}}';
comment on column "posts"."brief" is 'svgrid:{"field":"brief","header":"Brief","width":260,"fieldType":"longText"}';
comment on column "posts"."link" is 'svgrid:{"field":"link","header":"Link","width":220,"fieldType":"url"}';
comment on table "posts" is 'svgrid:{"v":1,"name":"Posts","position":0,"primaryField":"title","order":["title","stage","channels","author","campaign","publish","cover","words","brief","link"],"extra":[],"views":[{"id":"plan","name":"Content plan","type":"grid","color":{"mode":"field","field":"stage"},"state":{"sorting":[{"id":"publish","desc":false}],"grouping":[],"columnWidths":{"title":300,"stage":130,"channels":200,"author":160,"campaign":170,"publish":160,"cover":120,"words":100,"brief":260,"link":220},"columnPinning":{"left":["title"],"right":[]},"columnOrder":["title","stage","channels","author","campaign","publish","cover","words","brief","link"],"hiddenColumns":[],"globalFilter":"","columnFilters":{},"facetFilters":{}},"rowHeight":44},{"id":"pipeline","name":"Pipeline","type":"kanban","stackBy":"stage"},{"id":"calendar","name":"Publishing calendar","type":"calendar","dateField":"publish","color":{"mode":"field","field":"stage"}},{"id":"covers","name":"Covers","type":"gallery","coverField":"cover"},{"id":"pitch","name":"Pitch an idea","type":"form","formFields":["title","channels","author","campaign","brief"],"formDescription":"Tell the editors what you want to write. They pick it up in Monday planning."}]}';
comment on column "campaigns"."name" is 'svgrid:{"field":"name","header":"Campaign","width":200,"fieldType":"text"}';
comment on column "campaigns"."goal" is 'svgrid:{"field":"goal","header":"Goal","width":280,"fieldType":"text"}';
comment on column "campaigns"."owner" is 'svgrid:{"field":"owner","header":"Owner","width":160,"fieldType":"user"}';
comment on column "campaigns"."starts" is 'svgrid:{"field":"starts","header":"Starts","width":160,"fieldType":"date","fieldProps":{"dateFormat":"friendly"}}';
comment on column "campaigns"."ends" is 'svgrid:{"field":"ends","header":"Ends","width":160,"fieldType":"date","fieldProps":{"dateFormat":"friendly"}}';
comment on table "campaigns" is 'svgrid:{"v":1,"name":"Campaigns","position":1,"primaryField":"name","order":["name","goal","owner","starts","ends","posts","words"],"extra":[{"field":"posts","header":"Posts","width":320,"fieldType":"link","fieldProps":{"table":"posts","multiple":true,"inverse":"campaign"}},{"field":"words","header":"Words","width":110,"fieldType":"rollup","fieldProps":{"linkField":"posts","field":"words","aggregation":"SUM"}}],"views":[{"id":"campaigns","name":"All campaigns","type":"grid"},{"id":"when","name":"Campaign calendar","type":"calendar","dateField":"starts","endField":"ends"}]}';

